<main id="almaden-user-access-manager" class="almaden-app-content-shell flex-1 pb-16">
	<style>
	#almaden-user-access-manager .uam-grid{display:grid;grid-template-columns:minmax(220px,.7fr) minmax(0,1fr);gap:24px}#almaden-user-access-manager .uam-card{border:1px solid #e5e7eb;border-radius:24px;background:#fff;padding:24px;box-shadow:0 1px 3px rgba(15,23,42,.04)}#almaden-user-access-manager input{width:100%;border:0;border-bottom:1px solid #cbd5e1;background:transparent;padding:12px 0;outline:0}#almaden-user-access-manager .uam-results{position:absolute;z-index:10;left:0;right:0;margin-top:4px;border:1px solid #e5e7eb;border-radius:14px;background:#fff;box-shadow:0 12px 30px rgba(15,23,42,.12);overflow:hidden}.uam-result,.uam-resource{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 14px;border-bottom:1px solid #f1f5f9}.uam-result{width:100%;border:0;background:#fff;text-align:left;cursor:pointer}.uam-result:hover{background:#f8fafc}.uam-resource:last-child,.uam-result:last-child{border-bottom:0}.uam-resource button{border:1px solid #111827;border-radius:999px;background:#111827;color:#fff;padding:7px 12px;font-size:12px;font-weight:700;cursor:pointer}.uam-resource button.is-remove{border-color:#fecaca;background:#fff;color:#b91c1c}.uam-tabs{display:flex;gap:8px;margin:20px 0}.uam-tabs button{border:1px solid #e5e7eb;border-radius:999px;background:#fff;padding:10px 16px;font-weight:700;cursor:pointer}.uam-tabs button.is-active{background:#111827;color:#fff;border-color:#111827}.uam-panels{display:grid;grid-template-columns:1fr 1fr;gap:16px}.uam-panel{min-height:280px;border:1px solid #e5e7eb;border-radius:18px;padding:16px;background:#fafafa}.uam-muted{color:#64748b}.uam-hidden{display:none}@media(max-width:900px){#almaden-user-access-manager .uam-grid,.uam-panels{grid-template-columns:1fr}}
	</style>
	<section class="py-10"><p class="mb-3 text-xs font-semibold uppercase tracking-[0.3em] text-gray-400">Administración</p><h1 class="text-4xl font-bold tracking-tight text-black sm:text-5xl"><?php echo esc_html( almaden_bookster_get_user_access_manager_title() ); ?></h1><p class="mt-4 max-w-3xl text-lg leading-8 text-gray-600">Busca un usuario de WordPress y administra manualmente su acceso a cursos y ebooks.</p></section>
	<section class="uam-grid">
		<aside class="uam-card"><h2 class="text-xl font-bold">Usuario</h2><div style="position:relative;margin-top:18px"><label for="uam-user-search" class="text-sm font-semibold">Buscar por nombre o email</label><input id="uam-user-search" type="search" autocomplete="off" placeholder="Escribe al menos 2 caracteres..."><div id="uam-user-results" class="uam-results uam-hidden"></div></div><div id="uam-user-profile" class="uam-hidden" style="margin-top:24px"><div style="display:flex;align-items:center;gap:14px"><img id="uam-user-avatar" src="" alt="" style="width:64px;height:64px;border-radius:50%;object-fit:cover"><div><h3 id="uam-user-name" class="text-lg font-bold"></h3><p id="uam-user-email" class="uam-muted"></p></div></div><div class="uam-tabs"><button type="button" data-uam-type="course" class="is-active">CURSOS</button><button type="button" data-uam-type="ebook">EBOOKS</button></div></div><p id="uam-empty" class="uam-muted" style="margin-top:24px">Selecciona un usuario para administrar sus accesos.</p></aside>
		<div id="uam-resource-area" class="uam-hidden"><div class="uam-panels"><section class="uam-card"><h2 class="text-xl font-bold">Buscar recursos</h2><input id="uam-resource-search" type="search" placeholder="Filtrar cursos o ebooks..."><div id="uam-available" style="margin-top:14px"></div></section><section class="uam-card"><h2 class="text-xl font-bold">Tiene acceso</h2><div id="uam-assigned" style="margin-top:14px"></div></section></div></div>
	</section>
</main>
<script>
(function(){const root=document.getElementById('almaden-user-access-manager');if(!root)return;const ajax=<?php echo wp_json_encode(admin_url('admin-ajax.php')); ?>,nonce=<?php echo wp_json_encode(wp_create_nonce('almaden_user_access_manager')); ?>;let user=null,type='course',items=[];const $=id=>document.getElementById(id);function request(data){data.action='almaden_user_access_manager';data.nonce=nonce;return fetch(ajax,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)}).then(r=>r.json())}function render(){const term=($('uam-resource-search').value||'').toLowerCase();const filtered=items.filter(i=>i.title.toLowerCase().includes(term));$('uam-available').innerHTML=filtered.filter(i=>!i.has_access).map(i=>row(i,false)).join('')||'<p class="uam-muted">No hay recursos disponibles.</p>';$('uam-assigned').innerHTML=filtered.filter(i=>i.has_access).map(i=>row(i,true)).join('')||'<p class="uam-muted">Este usuario todavía no tiene accesos manuales.</p>'}function row(item,assigned){return '<div class="uam-resource"><span>'+escapeHtml(item.title)+'</span><button type="button" class="'+(assigned?'is-remove':'')+'" data-resource="'+item.id+'" data-enabled="'+(assigned?'0':'1')+'">'+(assigned?'REMOVE':'ADD')+'</button></div>'}function escapeHtml(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function load(){if(!user)return;request({manager_action:'load_resources',user_id:user.id,type:type}).then(r=>{if(!r.success)return;items=r.data||[];render()})}$('uam-user-search').addEventListener('input',function(){const term=this.value.trim();if(term.length<2){$('uam-user-results').classList.add('uam-hidden');return}request({manager_action:'search_users',term:term}).then(r=>{const users=r.success?r.data:[];$('uam-user-results').innerHTML=users.map(u=>'<button type="button" class="uam-result" data-user="'+u.id+'"><span><strong>'+escapeHtml(u.name)+'</strong><br><small class="uam-muted">'+escapeHtml(u.email)+'</small></span></button>').join('')||'<div class="uam-result uam-muted">No se encontraron usuarios.</div>';$('uam-user-results').classList.remove('uam-hidden')})});$('uam-user-results').addEventListener('click',function(e){const b=e.target.closest('[data-user]');if(!b)return;request({manager_action:'search_users',term:b.querySelector('small').textContent}).then(r=>{const found=(r.data||[]).find(u=>String(u.id)===b.dataset.user);if(!found)return;user=found;$('uam-user-results').classList.add('uam-hidden');$('uam-user-search').value=found.name;$('uam-user-profile').classList.remove('uam-hidden');$('uam-empty').classList.add('uam-hidden');$('uam-resource-area').classList.remove('uam-hidden');$('uam-user-avatar').src=found.avatar;$('uam-user-name').textContent=found.name;$('uam-user-email').textContent=found.email;load()})});root.querySelectorAll('[data-uam-type]').forEach(b=>b.addEventListener('click',function(){root.querySelectorAll('[data-uam-type]').forEach(x=>x.classList.remove('is-active'));this.classList.add('is-active');type=this.dataset.uamType;load()}));$('uam-resource-search').addEventListener('input',render);$('uam-resource-area').addEventListener('click',function(e){const b=e.target.closest('[data-resource]');if(!b||!user)return;b.disabled=true;request({manager_action:'toggle_access',user_id:user.id,type:type,resource_id:b.dataset.resource,enabled:b.dataset.enabled}).then(r=>{if(r.success){items=r.data||[];render()}else b.disabled=false})})})();
</script>
<?php almaden_bookster_render_app_shell_end();
